package me.pieralini.Aula6.Exercicio5;
import java.util.*; public class Main { public static void main(String[] args){Scanner s=new Scanner(System.in);ArrayList<Agente> pessoas=new ArrayList<>();while(true){System.out.println("1-Empresario 2-Professor 3-Advogado 4-Apresentar 5-Ativar agente 0-Sair");int op=Integer.parseInt(s.nextLine());if(op==0)break;if(op>=1&&op<=3){System.out.print("Nome: ");String n=s.nextLine();System.out.print("Dado da profissao: ");String d=s.nextLine();pessoas.add(op==1?new Empresario(n,d):op==2?new Professor(n,d):new Advogado(n,d));}else if(op==4)pessoas.forEach(Agente::apresentacao);else if(op==5){System.out.print("Indice: ");int i=Integer.parseInt(s.nextLine());if(i>=0&&i<pessoas.size())pessoas.get(i).modo_agente_on();}}} }
